// ignore_for_file: avoid_print
// Composes the README style-catalog sheets from the cells generated by
// test/readme_images_test.dart. Run:
//   flutter test test/readme_images_test.dart --tags samples
//   dart run tool/make_readme_images.dart
import 'dart:io';

import 'package:image/image.dart' as img;

const cellSize = 460;
const labelHeight = 44;
const gap = 14;
const columns = 3;

void main() {
  final rawDir = Directory('build/readme_raw');
  if (!rawDir.existsSync()) {
    print('run the readme_images_test first');
    exit(1);
  }
  Directory('doc').createSync(recursive: true);

  // Group files by sheet name: <sheet>__<NN>__<Label>.png
  final sheets = <String, List<File>>{};
  for (final file in rawDir.listSync().whereType<File>()) {
    final name = file.uri.pathSegments.last;
    if (!name.endsWith('.png')) continue;
    final sheet = name.split('__').first;
    sheets.putIfAbsent(sheet, () => []).add(file);
  }

  final font = img.arial24;
  for (final entry in sheets.entries) {
    final files = entry.value
      ..sort((a, b) => a.path.compareTo(b.path));
    final rows = (files.length / columns).ceil();
    final width = columns * cellSize + (columns + 1) * gap;
    final height = rows * (cellSize + labelHeight) + (rows + 1) * gap;
    final sheet = img.Image(width: width, height: height);
    img.fill(sheet, color: img.ColorRgb8(255, 255, 255));

    for (var i = 0; i < files.length; i++) {
      final cell = img.decodePng(files[i].readAsBytesSync())!;
      final resized = cell.width == cellSize
          ? cell
          : img.copyResize(cell, width: cellSize, height: cellSize);
      final col = i % columns;
      final row = i ~/ columns;
      final x = gap + col * (cellSize + gap);
      final y = gap + row * (cellSize + labelHeight + gap);
      img.compositeImage(sheet, resized, dstX: x, dstY: y);

      final label = files[i].uri.pathSegments.last
          .split('__')
          .last
          .replaceAll('.png', '');
      final textWidth = label.length * 12; // arial24 ≈ 12px advance
      img.drawString(
        sheet,
        label,
        font: font,
        x: x + (cellSize - textWidth) ~/ 2,
        y: y + cellSize + 10,
        color: img.ColorRgb8(40, 40, 40),
      );
    }

    final out = File('doc/${entry.key}.png');
    out.writeAsBytesSync(img.encodePng(sheet));
    print('wrote ${out.path} (${files.length} cells, ${width}x$height)');
  }
}
